using System;
using System.Collections;
using System.IO;
using System.Linq;
using EchoStation.Echo;
using EchoStation.SalvageExpansion.Editor;
using EchoStation.SalvageNext;
using EchoStation.Tests.Player;
using NUnit.Framework;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEngine.UI;
using Object=UnityEngine.Object;
namespace EchoStation.SalvageExpansion.Tests
{
    public sealed class ExpansionIntegrationTests
    {
        static Scene prior,scene;static ExpansionWorld world;static FacilityController facility;static EnvironmentHazards hazards;static ExpansionMission mission;static ExpansionEcho echo;static ExpansionStreaming stream;static ExpansionPersistence save;static SyntheticInputScope input;static bool background;static float scale;
        static IEnumerator Wait(Func<bool> predicate,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!predicate()){Assert.That(Time.realtimeSinceStartup,Is.LessThan(end),label);yield return null;}}
        static IEnumerator Boot()
        {
            background=Application.runInBackground;Application.runInBackground=true;scale=Time.timeScale;prior=SceneManager.GetActiveScene();input=new SyntheticInputScope();var op=EditorSceneManager.LoadSceneAsyncInPlayMode(ExpansionSceneBuilder.ScenePath,new LoadSceneParameters(LoadSceneMode.Additive));while(!op.isDone)yield return null;scene=SceneManager.GetSceneByPath(ExpansionSceneBuilder.ScenePath);SceneManager.SetActiveScene(scene);world=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<ExpansionWorld>()).Single();facility=world.GetComponent<FacilityController>();hazards=world.GetComponent<EnvironmentHazards>();mission=world.GetComponent<ExpansionMission>();echo=world.GetComponent<ExpansionEcho>();stream=world.GetComponent<ExpansionStreaming>();save=world.GetComponent<ExpansionPersistence>();save.ConfigureTests(Path.GetFullPath("Library/EchoStation/SalvageExpansion/Tests/Integration_"+Guid.NewGuid().ToString("N")));yield return Wait(()=>stream.Owner!=null&&!stream.Blocking,25,"Initial streamed room ready");world.Input.SetApplicationFocus(true);world.Input.SetPointerCaptured(true);yield return null;
        }
        static FacilityDevice Device(FacilityDeviceKind kind)=>facility.Devices.Single(d=>d.Kind==kind);
        static void Aim(Transform t){var delta=t.position-world.Motor.View.position;float yaw=Mathf.Atan2(delta.x,delta.z)*Mathf.Rad2Deg,pitch=-Mathf.Atan2(delta.y,new Vector2(delta.x,delta.z).magnitude)*Mathf.Rad2Deg;world.Motor.RestorePose(world.transform.position,yaw,pitch);world.Input.SetPointerCaptured(true);Physics.SyncTransforms();Assert.That(delta.magnitude,Is.LessThan(3.3f),"Aim within interaction range "+t.name);}
        static void Equip(string id){if(world.Inventory.HeldId!=null)Assert.That(world.Inventory.TryUnequip(out _),Is.True);Assert.That(world.Inventory.TryEquip(id,out var error),Is.True,error);world.SyncViews();}
        static IEnumerator Walk(params Vector3[] points)
        {
            foreach(var p in points){var delta=p-world.transform.position;delta.y=0;float yaw=Mathf.Atan2(delta.x,delta.z)*Mathf.Rad2Deg;world.Motor.RestorePose(world.transform.position,yaw,0);world.Input.SetPointerCaptured(true);InputSystem.QueueStateEvent(input.Keyboard,new KeyboardState(Key.W));float end=Time.realtimeSinceStartup+15;while(Vector2.Distance(new Vector2(world.transform.position.x,world.transform.position.z),new Vector2(p.x,p.z))>.22f){Assert.That(hazards.Failed,Is.False,"Route pressure failure");if(Time.realtimeSinceStartup>=end){string blocks=string.Join(",",Physics.OverlapCapsule(world.transform.position+Vector3.up*.4f,world.transform.position+Vector3.up*1.4f,.7f,~0,QueryTriggerInteraction.Ignore).Select(c=>c.name+"@"+c.transform.position));Assert.Fail("Walk blocked at "+world.transform.position+" toward "+p+" UI="+world.Pause.Blocked+" blockers="+blocks);}yield return null;}InputSystem.QueueStateEvent(input.Keyboard,new KeyboardState());yield return null;}
        }
        static IEnumerator Route(bool valve)
        {
            yield return Walk(new Vector3(9,0,12),new Vector3(9,0,valve?6:18));if(valve){yield return Walk(new Vector3(14.5f,0,6));Equip(ExpansionCatalog.Wrench);var d=Device(FacilityDeviceKind.Valve);Aim(d.transform);var tools=world.GetComponent<ExpansionTools>();Assert.That(tools.Request(d),Is.True);var c=tools.Center;tools.BeginStroke(c+Vector2.right*100);tools.DragStroke(c+new Vector2(70.71f,-70.71f));tools.DragStroke(c+Vector2.down*100);Assert.That(facility.ValveClosed,Is.True);yield return Walk(new Vector3(21,0,6),new Vector3(21,0,12),new Vector3(26,0,12));}
            else{Equip(ExpansionCatalog.Battery);Aim(Device(FacilityDeviceKind.FanSocket).transform);Assert.That(facility.Socket(Device(FacilityDeviceKind.FanSocket)),Is.True,world.Message);yield return Walk(new Vector3(15,0,18),new Vector3(15,0,16.5f),new Vector3(21,0,16.5f),new Vector3(21,0,12),new Vector3(26,0,12));}
            yield return Walk(new Vector3(26,0,10));Equip(ExpansionCatalog.Insulator);Aim(Device(FacilityDeviceKind.Isolator).transform);Assert.That(world.GetComponent<ExpansionTools>().Request(Device(FacilityDeviceKind.Isolator)),Is.True,world.Message);
            if(valve){Equip(ExpansionCatalog.Battery);Aim(Device(FacilityDeviceKind.DataSocket).transform);Assert.That(facility.Socket(Device(FacilityDeviceKind.DataSocket)),Is.True,world.Message);yield return Wait(()=>facility.DataReady,12,"Optional data validation");}
            Equip(ExpansionCatalog.Wrench);yield return Walk(new Vector3(28.2f,0,12.8f));foreach(var d in facility.Devices.Where(d=>d.Kind>=FacilityDeviceKind.ClampA)){Aim(d.transform);if(Vector3.Distance(d.transform.position,world.Motor.View.position)>2.9f){yield return Walk(new Vector3(29,0,13.4f));Aim(d.transform);}Assert.That(world.GetComponent<ExpansionTools>().Request(d),Is.True,world.Message);}yield return Walk(new Vector3(30,0,14));Aim(world.Actors[ExpansionCatalog.Core].transform);Assert.That(world.TryPickupFromView(),Is.True,world.Message);yield return null;Assert.That(facility.CoreRemoved,Is.True);yield return Walk(new Vector3(26,0,12),new Vector3(21,0,12),new Vector3(21,0,6),new Vector3(9,0,6),new Vector3(9,0,12),new Vector3(5,0,12));Assert.That(world.BeginDelivery(),Is.True,world.Message);Assert.That(world.ConfirmDelivery(),Is.True,world.Message);Assert.That(mission.Completed,Is.False);Assert.That(mission.OpenBoard(),Is.True);Assert.That(mission.RequestCompletion(),Is.True);Assert.That(mission.ConfirmCompletion(),Is.True);Assert.That(mission.Completed,Is.True);Assert.That(facility.Archived,Is.EqualTo(valve));
        }
        [UnityTest]public IEnumerator FanUpperRouteCompletesObjectiveThroughActualMovementAndStreaming(){yield return new EnterPlayMode();yield return Boot();yield return Route(false);Assert.That(stream.Owner.Failures,Is.Zero);}
        [UnityTest]public IEnumerator ValveLowerRouteAndOptionalDataCompleteWithExplicitEnding(){yield return new EnterPlayMode();yield return Boot();yield return Route(true);Assert.That(mission.ConfirmCompletion(),Is.False);}
        [UnityTest]public IEnumerator ActualSceneHasIsolatedNavHeightSevenItemsAndSafeInitialSnapshot()
        {
            yield return new EnterPlayMode();yield return Boot();Assert.That(world.Actors.Count,Is.EqualTo(7));Assert.That(facility.Devices.Length,Is.EqualTo(7));Assert.That(stream.Room(0).GetComponent<RoomVisual>().Region.size.y,Is.GreaterThan(4));Assert.That(UnityEditor.AssetDatabase.GetAssetPath(scene.GetRootGameObjects().Single().GetComponent<Unity.AI.Navigation.NavMeshSurface>().navMeshData),Does.StartWith(ExpansionSceneBuilder.Generated+"/Nav"));Assert.That(save.Save(),Is.True,world.Message);Assert.That(save.Load(),Is.True,world.Message);yield return Wait(()=>!stream.Blocking,25,"Read epoch resources");Assert.That(GameRuntimeOptions.UseLLM,Is.False);
        }
        [UnityTest]public IEnumerator BoardInventoryEchoAreMutuallyExclusiveAndTutorialCanSkipAndReview()
        {
            yield return new EnterPlayMode();yield return Boot();Assert.That(mission.OpenBoard(),Is.True);float elapsed=mission.Elapsed,phase=hazards.Phase;yield return null;yield return null;Assert.That(mission.Elapsed,Is.EqualTo(elapsed));Assert.That(hazards.Phase,Is.EqualTo(phase));Assert.That(world.Backpack.Open(),Is.False);Assert.That(echo.OpenMenu(),Is.False);var canvas=world.transform.Find("ExpansionTaskBoard");canvas.Find("Panel/Skip").GetComponent<Button>().onClick.Invoke();Assert.That(mission.TutorialSkipped,Is.True);canvas.Find("Panel/Review").GetComponent<Button>().onClick.Invoke();Assert.That(mission.TutorialSkipped,Is.False);mission.CloseBoard();Assert.That(world.Backpack.Open(),Is.True);Assert.That(mission.OpenBoard(),Is.False);world.Backpack.Close();Assert.That(echo.OpenMenu(),Is.True);Assert.That(world.Backpack.Open(),Is.False);echo.CloseMenu();Assert.That(world.Pause.Blocked,Is.False);
        }
        [UnityTest]public IEnumerator FailureCanLoadAndRestartWholeSceneWithoutDuplicatingDeliveredItems()
        {
            yield return new EnterPlayMode();yield return Boot();Assert.That(save.Save(),Is.True,world.Message);world.Motor.RestorePose(new Vector3(30,.05f,14),0,0);hazards.Advance(1,false);hazards.Advance(1,false);Assert.That(hazards.Failed,Is.True);Assert.That(save.Save(),Is.False);Assert.That(save.Load(),Is.True,world.Message);yield return Wait(()=>!stream.Blocking,25,"Failure load room");Assert.That(hazards.Failed,Is.False);Assert.That(world.Inventory.Get(ExpansionCatalog.Core).Location,Is.EqualTo(InventoryItemLocation.World));mission.RestartNow();yield return Wait(()=>!stream.Blocking,25,"Restart room");Assert.That(mission.Elapsed,Is.LessThan(1));Assert.That(facility.Clamps,Is.Zero);Assert.That(facility.Charge,Is.EqualTo(90));Assert.That(world.Inventory.Board().OccupiedCells.Count,Is.EqualTo(8));Assert.That(world.Input.UiBlocked,Is.False);
        }
        [UnityTest]public IEnumerator ThreeQualityProfilesAndActualSceneFrameAreValid()
        {
            yield return new EnterPlayMode();yield return Boot();var graphics=world.GetComponent<ExpansionGraphics>();for(int i=0;i<3;i++){graphics.SetQuality((RecoveryQuality)i);yield return null;Assert.That(GraphicsSettings.currentRenderPipeline.name,Does.StartWith("Expansion_"+i));}graphics.SetQuality(RecoveryQuality.Medium);var camera=world.Motor.View.GetComponent<Camera>();var rt=new RenderTexture(1280,720,24);rt.Create();Texture2D image=null;var active=RenderTexture.active;try{camera.targetTexture=rt;RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=rt});RenderTexture.active=rt;image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();string path=ExpansionSceneBuilder.Evidence+"/Scene_"+Guid.NewGuid().ToString("N")+".png";File.WriteAllBytes(path,image.EncodeToPNG());var pixels=image.GetPixels();Assert.That(pixels.Average(p=>p.grayscale),Is.GreaterThan(.02));Assert.That(pixels.Max(p=>p.grayscale)-pixels.Min(p=>p.grayscale),Is.GreaterThan(.1));}finally{camera.targetTexture=null;RenderTexture.active=active;rt.Release();Object.Destroy(rt);if(image)Object.Destroy(image);}
        }
        [UnityTest]public IEnumerator EchoTravelsFromSpawnToRaisedDeviceAndOnlyReturnsInformation()
        {
            yield return new EnterPlayMode();yield return Boot();world.Motor.RestorePose(new Vector3(9,.05f,18),0,0);var d=Device(FacilityDeviceKind.FanSocket);Aim(d.transform);var target=d.GetComponent<EchoStation.World.WorldTarget>();echo.Discover(target);Assert.That(echo.Command(ScriptCommands.Investigate(target.Id)),Is.True,world.Message);yield return Wait(()=>echo.Report(target.Id)!="尚无扫描信息。",20,"Echo actual travel and raised-device scan");Assert.That(echo.Report(target.Id),Does.Contain("通风"));Assert.That(facility.FanPowered,Is.False);Assert.That(facility.Charge,Is.EqualTo(90));Assert.That(echo.Battery.Charge,Is.LessThan(93));
        }
        [UnityTest]public IEnumerator SteamFogActuallyRendersHalfResolutionAndSupplySuppressesIt()
        {
            yield return new EnterPlayMode();yield return Boot();world.Motor.RestorePose(new Vector3(9,.05f,18),90,0);world.Input.SetPointerCaptured(true);var steam=hazards.Zones.Single(z=>z.Kind==EnvironmentHazardKind.Steam);while(hazards.Signal(steam)!=HazardSignal.Active)hazards.Advance(.1f,false);var field=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<ExpansionFogField>()).Single();var camera=world.Motor.View.GetComponent<Camera>();Assert.That(field.ShouldRender(camera),Is.True);var rt=new RenderTexture(1280,720,24);rt.Create();try{camera.targetTexture=rt;RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=rt});Assert.That(field.LastRecordedFrame,Is.EqualTo(Time.frameCount));Assert.That(field.LastWidth,Is.EqualTo(640));Assert.That(field.LastHeight,Is.EqualTo(360));Equip(ExpansionCatalog.Battery);Aim(Device(FacilityDeviceKind.FanSocket).transform);Assert.That(facility.Socket(Device(FacilityDeviceKind.FanSocket)),Is.True);Assert.That(field.ShouldRender(camera),Is.False);world.GetComponent<ExpansionGraphics>().SetQuality(RecoveryQuality.Low);Assert.That(field.ShouldRender(camera),Is.False);}finally{camera.targetTexture=null;rt.Release();Object.Destroy(rt);}
        }
        [UnityTest]public IEnumerator RealLootRequiresRotationThenBatchDeliveryCountsOnlyConfirmedOptionalValue()
        {
            yield return new EnterPlayMode();yield return Boot();echo.Command(ScriptCommands.Wait());world.Motor.RestorePose(new Vector3(26,.05f,10),90,0);Equip(ExpansionCatalog.Insulator);Aim(Device(FacilityDeviceKind.Isolator).transform);Assert.That(facility.TryIsolate(Device(FacilityDeviceKind.Isolator)),Is.True);world.Motor.RestorePose(new Vector3(29,.05f,13.4f),0,0);Equip(ExpansionCatalog.Wrench);foreach(var d in facility.Devices.Where(d=>d.Kind>=FacilityDeviceKind.ClampA)){Aim(d.transform);Assert.That(facility.TryReleaseClamp(d),Is.True,world.Message);}world.Motor.RestorePose(new Vector3(30,.05f,14),0,0);Aim(world.Actors[ExpansionCatalog.Core].transform);Assert.That(world.TryPickupFromView(),Is.True,world.Message);world.Motor.RestorePose(new Vector3(14.5f,.05f,18),90,0);Aim(world.Actors[ExpansionCatalog.Samples].transform);Assert.That(world.TryPickupFromView(),Is.False);Assert.That(world.Inventory.Get(ExpansionCatalog.Samples).Location,Is.EqualTo(InventoryItemLocation.World));var row=world.Inventory.Get(ExpansionCatalog.Core);Assert.That(world.Backpack.Open(),Is.True);Assert.That(world.Backpack.BeginDrag(row.X,row.Y),Is.True);world.Backpack.Rotate();Assert.That(world.Backpack.CommitDrag(row.X+2,row.Y),Is.True);world.Backpack.Close();world.Input.SetPointerCaptured(true);Assert.That(world.TryPickupFromView(),Is.True,world.Message);world.Motor.RestorePose(new Vector3(5,.05f,12),90,0);Assert.That(world.BeginDelivery(),Is.True);world.CancelDelivery();Assert.That(mission.ExtraValue,Is.Zero);Assert.That(world.BeginDelivery(),Is.True);Assert.That(world.ConfirmDelivery(),Is.True);Assert.That(mission.ExtraValue,Is.EqualTo(4));Assert.That(world.ConfirmDelivery(),Is.False);Assert.That(mission.ExtraValue,Is.EqualTo(4));
        }
        [UnityTest]public IEnumerator DroppedItemCarvesRealNavigationAndPickupReleasesTheHole()
        {
            yield return new EnterPlayMode();yield return Boot();echo.Command(ScriptCommands.Wait());world.Motor.RestorePose(new Vector3(5,.05f,12),90,0);Equip(ExpansionCatalog.Wrench);var actor=world.Actors[ExpansionCatalog.Wrench];var obstacle=actor.GetComponent<UnityEngine.AI.NavMeshObstacle>();Assert.That(obstacle,Is.Not.Null);Assert.That(obstacle.enabled,Is.False);var point=new Vector3(6.2f,.05f,12);Assert.That(UnityEngine.AI.NavMesh.SamplePosition(point,out _,.15f,UnityEngine.AI.NavMesh.AllAreas),Is.True);Assert.That(world.TryDrop(ExpansionCatalog.Wrench),Is.True,world.Message);Assert.That(obstacle.enabled&&obstacle.carving,Is.True);yield return Wait(()=>!UnityEngine.AI.NavMesh.SamplePosition(point,out _,.15f,UnityEngine.AI.NavMesh.AllAreas),4,"Actual dynamic carve");Aim(actor.transform);Assert.That(world.TryPickupFromView(),Is.True,world.Message);Assert.That(obstacle.enabled,Is.False);yield return Wait(()=>UnityEngine.AI.NavMesh.SamplePosition(point,out _,.15f,UnityEngine.AI.NavMesh.AllAreas),4,"Dynamic carve removed after pickup");
        }
        [UnityTearDown]public IEnumerator Cleanup()
        {
            if(!Application.isPlaying)yield break;InputSystem.QueueStateEvent(input.Keyboard,new KeyboardState());var owner=stream?stream.Owner:null;if(prior.IsValid())SceneManager.SetActiveScene(prior);if(scene.IsValid()&&scene.isLoaded){var op=SceneManager.UnloadSceneAsync(scene);while(!op.isDone)yield return null;}if(owner!=null)yield return Wait(()=>owner.IsClosed,25,"All Addressables handles retired");input?.Dispose();if(input!=null)Assert.That(input.IsRestored,Is.True);input=null;Time.timeScale=scale;Application.runInBackground=background;yield return new ExitPlayMode();
        }
    }
}
